import React, { useState } from 'react';
import { AnalysisReport, GroundingSource } from '../types';
import { Network, FileText, CheckCircle2, AlertOctagon, Activity, ExternalLink, Users, TowerControl, Shield, ShieldAlert, UserCheck, Scale, SearchX, RefreshCw } from 'lucide-react';

interface Props {
  report: AnalysisReport;
  sources: GroundingSource[];
  searchEntryPoint?: string;
  isPrinting?: boolean;
}

const DeepDive: React.FC<Props> = ({ report, sources, searchEntryPoint, isPrinting = false }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'network' | 'evidence' | 'factcheck' | 'critique' | 'people'>('dashboard');

  const tabs = [
    { id: 'dashboard', label: 'Dashboard', icon: Activity },
    { id: 'network', label: 'Network', icon: Network },
    { id: 'people', label: 'Key Figures', icon: UserCheck },
    { id: 'evidence', label: 'Evidence', icon: FileText },
    { id: 'factcheck', label: 'Fact Check', icon: CheckCircle2 },
    { id: 'critique', label: 'Critique', icon: AlertOctagon },
  ];

  return (
    <div className="mt-8 bg-slate-900/50 backdrop-blur-md border border-slate-700/50 rounded-2xl shadow-xl overflow-hidden min-h-[600px]">
      {!isPrinting && (
        <div className="flex border-b border-slate-700/50 overflow-x-auto">
            {tabs.map((tab) => (
            <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center gap-2 px-6 py-4 text-sm font-medium transition-colors whitespace-nowrap ${
                activeTab === tab.id
                    ? 'text-cyan-400 border-b-2 border-cyan-400 bg-slate-800/30'
                    : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/20'
                }`}
            >
                <tab.icon className="w-4 h-4" />
                {tab.label}
            </button>
            ))}
        </div>
      )}

      <div className="p-6 space-y-8">
        {(activeTab === 'dashboard' || isPrinting) && (
          <div className="animate-in fade-in duration-300">
             {isPrinting && <h2 className="text-xl font-bold text-cyan-400 mb-4 border-b border-slate-700 pb-2 flex items-center gap-2"><Activity className="w-5 h-5"/> Dashboard</h2>}

             {/* DRY FACTS SECTION */}
             {report.dryFacts && report.dryFacts.length > 0 && (
              <div className="col-span-full mb-6 bg-slate-800/60 p-5 rounded-xl border border-blue-500/30 shadow-[0_0_15px_rgba(59,130,246,0.1)]">
                <h3 className="text-blue-400 font-bold mb-4 flex items-center gap-2 uppercase tracking-wider text-sm">
                  <CheckCircle2 className="w-4 h-4" /> Undisputed Facts (The Baseline)
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {report.dryFacts.map((fact, i) => (
                    <div key={i} className="flex items-start gap-3 bg-slate-900/50 p-3 rounded-lg border border-slate-700/50">
                      <div className="flex-shrink-0 mt-1.5 w-1.5 h-1.5 rounded-full bg-blue-500"></div>
                      <div>
                        <p className="text-slate-200 text-sm font-medium">{fact.fact}</p>
                        <div className="flex gap-2 mt-1.5">
                          <span className="text-[10px] text-slate-500 uppercase bg-slate-950 px-1.5 py-0.5 rounded border border-slate-800">{fact.context}</span>
                          <span className="text-[10px] text-blue-400/80 uppercase">{fact.source}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
             )}

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-slate-800/40 p-5 rounded-xl border border-slate-700/50">
                <h3 className="text-slate-300 font-semibold mb-4 flex items-center gap-2">
                    <Activity className="w-4 h-4 text-cyan-400" /> Key Insights
                </h3>
                <ul className="space-y-3">
                    {report.summary.keyPoints.map((pt, i) => (
                    <li key={i} className="flex gap-3 text-sm text-slate-300">
                        <span className="text-cyan-500 font-bold">•</span> {pt}
                    </li>
                    ))}
                </ul>
                </div>
                <div className="space-y-6">
                  <div className="bg-slate-800/40 p-5 rounded-xl border border-slate-700/50">
                      <h3 className="text-slate-300 font-semibold mb-2">Emotional Tone</h3>
                      <div className="flex items-center gap-4">
                          <div className="flex-1 h-3 bg-slate-700 rounded-full overflow-hidden">
                              <div 
                              className="h-full bg-gradient-to-r from-blue-500 to-purple-500" 
                              style={{ width: `${report.summary.emotionalTone.score}%` }}
                              />
                          </div>
                          <span className="text-sm font-mono text-purple-400">{report.summary.emotionalTone.score}% Intensity</span>
                      </div>
                      <p className="mt-2 text-xs text-slate-400">{report.summary.emotionalTone.analysis}</p>
                  </div>
                  <div className="bg-slate-800/40 p-5 rounded-xl border border-slate-700/50">
                      <h3 className="text-slate-300 font-semibold mb-2">AI Generated Content Probability</h3>
                      <div className="flex items-center justify-between">
                          <span className="text-sm text-slate-300">{report.summary.aiGenerated.status}</span>
                          <span className="text-xs text-slate-500 px-2 py-1 bg-slate-900 rounded border border-slate-700">Detector Output</span>
                      </div>
                      <p className="mt-2 text-xs text-slate-400">{report.summary.aiGenerated.analysis}</p>
